import type { ComponentType, LazyExoticComponent } from "react"
import type { Tool } from "ai"
import type { z } from "zod"
import { fableRegistry, type DataSourceRegistry } from "@/lib/fable-ui/core"

export class ToolPayloadError extends Error {
  constructor(message: string) {
    super(message)
    this.name = "ToolPayloadError"
  }
}

export type ToolRenderHandlers = {
  onSuggestedAction?: (action: {
    label: string
    prompt: string
    description?: string
  }) => void
  onConfirm?: (confirmation: { id: string; label: string }) => void
  onCancel?: (confirmation: { id: string; label: string }) => void
  onFormSubmit?: (values: Record<string, string | number | boolean>) => void
  onRowAction?: (action: { id: string; rowId: string }) => void
}

export type ToolPartLike = {
  type: string
  toolName?: string
  toolCallId?: string
  state?: string
  input?: unknown
  output?: unknown
  errorText?: string
  toolMetadata?: {
    fableState?: "loading" | "empty" | "error" | "disabled"
  }
}

export type FableRenderableComponent<TProps extends object> =
  ComponentType<TProps> | LazyExoticComponent<ComponentType<TProps>>

export interface FableComponent<
  TSchema extends z.ZodType = z.ZodType,
  TProps extends object = Record<string, unknown>,
  TTool extends Tool = Tool,
> {
  name: string
  schema: TSchema
  tool: TTool
  renderer: {
    Component: FableRenderableComponent<TProps>
    loadingProps: TProps
    streamingProps?: (input: unknown) => TProps
    emptyProps: TProps
    errorProps: (description: string, part?: ToolPartLike) => TProps
    toProps: (data: z.infer<TSchema>, handlers: ToolRenderHandlers) => TProps
  }
}

export type FableToolRegistry = Record<
  string,
  // Registry entries intentionally have heterogeneous component props.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  FableComponent<z.ZodType, any, Tool>
>

export function defineFableComponent<
  TSchema extends z.ZodType,
  TProps extends object,
  TTool extends Tool,
>(def: FableComponent<TSchema, TProps, TTool>) {
  return def
}

export function getToolNameFromPart(part: ToolPartLike) {
  if (part.toolName) {
    return part.toolName
  }

  if (part.type.startsWith("tool-")) {
    return part.type.slice("tool-".length)
  }

  return null
}

// move to utils or resources related files.
export function describeAvailableResources(
  registry: DataSourceRegistry = fableRegistry
) {
  return JSON.stringify(registry.getAgentResourceManifest(), null, 2)
}

import * as React from "react"
import type { ReactNode } from "react"

import {
  getToolNameFromPart,
  ToolPayloadError,
  type FableToolRegistry,
  type ToolPartLike,
  type ToolRenderHandlers,
} from "./definitions"

function UnknownToolPart({ name }: { name: string }) {
  return (
    <div
      role="alert"
      className="rounded-md border bg-muted/40 p-4 text-sm text-muted-foreground"
    >
      Unknown Fable tool part: <code>{name}</code>
    </div>
  )
}

function renderComponent(
  Component: FableToolRegistry[string]["renderer"]["Component"],
  props: Record<string, unknown>
) {
  return (
    <React.Suspense fallback={null}>
      <Component {...props} />
    </React.Suspense>
  )
}

export function renderFableToolPart({
  part,
  registry,
  handlers = {},
}: {
  part: ToolPartLike
  registry: FableToolRegistry
  handlers?: ToolRenderHandlers
}): ReactNode {
  const toolName = getToolNameFromPart(part)
  const def = toolName ? registry[toolName] : undefined

  if (!def) {
    return <UnknownToolPart name={toolName ?? part.type} />
  }

  const fableState = part.toolMetadata?.fableState
  const isDisabled = fableState === "disabled"

  if (fableState === "loading") {
    return renderComponent(def.renderer.Component, def.renderer.loadingProps)
  }

  if (part.state === "input-streaming") {
    if (!def.renderer.streamingProps) {
      return renderComponent(def.renderer.Component, def.renderer.loadingProps)
    }

    try {
      return renderComponent(
        def.renderer.Component,
        def.renderer.streamingProps(part.input)
      )
    } catch (error) {
      const description =
        error instanceof ToolPayloadError
          ? error.message
          : "Unexpected error rendering component."

      return renderComponent(
        def.renderer.Component,
        def.renderer.errorProps(description, part)
      )
    }
  }

  if (part.state === "output-error" || fableState === "error") {
    return renderComponent(
      def.renderer.Component,
      def.renderer.errorProps(
        part.errorText || "The tool result could not be rendered.",
        part
      )
    )
  }

  if (fableState === "empty") {
    return renderComponent(def.renderer.Component, def.renderer.emptyProps)
  }

  const parsed = def.schema.safeParse(part.output ?? part.input)

  if (!parsed.success) {
    return renderComponent(
      def.renderer.Component,
      def.renderer.errorProps(
        "The tool result did not match the expected data contract.",
        part
      )
    )
  }

  try {
    return renderComponent(def.renderer.Component, {
      ...def.renderer.toProps(parsed.data, handlers),
      isDisabled,
    })
  } catch (error) {
    const description =
      error instanceof ToolPayloadError
        ? error.message
        : "Unexpected error rendering component."

    return renderComponent(
      def.renderer.Component,
      def.renderer.errorProps(description, part)
    )
  }
}

export function FableToolPart({
  part,
  registry,
  handlers,
}: {
  part: ToolPartLike
  registry: FableToolRegistry
  handlers?: ToolRenderHandlers
}) {
  return <>{renderFableToolPart({ part, registry, handlers })}</>
}

import type { DataColumn, DataRow } from "./types"

export function getDataValue(row: DataRow, key: string): unknown {
  const cells = row.cells

  if (cells && typeof cells === "object" && key in cells) {
    return (cells as Record<string, unknown>)[key]
  }

  return key.split(".").reduce<unknown>((value, part) => {
    if (value && typeof value === "object" && part in value) {
      return (value as Record<string, unknown>)[part]
    }

    return undefined
  }, row)
}

export function normalizeDataValue(value: unknown) {
  if (value instanceof Date) {
    return value.toISOString()
  }

  if (value == null) {
    return ""
  }

  return String(value)
}

export function formatDataCell(row: DataRow, column: DataColumn) {
  const value = getDataValue(row, column.key)

  if (value == null) {
    return ""
  }

  if (column.type === "date" || column.type === "datetime") {
    const date = value instanceof Date ? value : new Date(String(value))

    if (!Number.isNaN(date.getTime())) {
      return column.type === "date" ? date.toLocaleDateString() : date.toLocaleString()
    }
  }

  return normalizeDataValue(value)
}

export function getRowId(row: DataRow) {
  const id = row.id ?? row._id ?? row.uid ?? row.orderId ?? row.order
  return id == null ? null : String(id)
}

import { getDataValue, normalizeDataValue } from "./format"
import type { DataColumn, DataQuery, DataQueryResult, DataRow } from "./types"

function matchesSearch(row: DataRow, query: string, columns?: DataColumn[]) {
  const keys = columns?.map((column) => column.key) ?? Object.keys(row)
  const normalizedQuery = query.trim().toLowerCase()

  if (!normalizedQuery) {
    return true
  }

  return keys.some((key) => normalizeDataValue(getDataValue(row, key)).toLowerCase().includes(normalizedQuery))
}

function matchesFilters(row: DataRow, filters: Record<string, unknown>) {
  return Object.entries(filters).every(([key, expected]) => {
    if (expected == null || expected === "" || (Array.isArray(expected) && expected.length === 0)) {
      return true
    }

    const value = getDataValue(row, key)

    if (Array.isArray(expected)) {
      return expected.map(String).includes(String(value))
    }

    if (typeof expected === "boolean") {
      return Boolean(value) === expected
    }

    return String(value).toLowerCase() === String(expected).toLowerCase()
  })
}

function compareValues(a: unknown, b: unknown) {
  if (typeof a === "number" && typeof b === "number") {
    return a - b
  }

  return normalizeDataValue(a).localeCompare(normalizeDataValue(b), undefined, {
    numeric: true,
    sensitivity: "base",
  })
}

export function queryLocalRows<Row extends DataRow>(
  rows: Row[],
  query: DataQuery = {},
  columns?: DataColumn[],
): DataQueryResult<Row> {
  const page = query.page ?? 1
  const pageSize = query.pageSize ?? (rows.length || 10)

  let nextRows = rows.filter((row) => matchesSearch(row, query.search ?? "", columns))
  nextRows = nextRows.filter((row) => matchesFilters(row, query.filters ?? {}))

  if (query.sort?.key) {
    const { key, direction } = query.sort
    nextRows = [...nextRows].sort((a, b) => {
      const result = compareValues(getDataValue(a, key), getDataValue(b, key))
      return direction === "desc" ? -result : result
    })
  }

  const totalRows = nextRows.length
  const start = (page - 1) * pageSize
  const pagedRows = nextRows.slice(start, start + pageSize)

  return {
    rows: pagedRows,
    totalRows,
    page,
    pageSize,
    nextCursor: start + pageSize < totalRows ? String(page + 1) : undefined,
    previousCursor: page > 1 ? String(page - 1) : undefined,
  }
}

import type {
  AgentResourceManifest,
  DataActionInput,
  DataActionResult,
  DataQuery,
  DataQueryResult,
  DataRow,
  DataSourceContext,
  DataSourceDriver,
  ResourceConfig,
  ResourceRuntime,
} from "./types"

function warnOnce(message: string) {
  if (process.env.NODE_ENV === "development") {
    console.warn(message)
  }
}

type RegisteredDriver = DataSourceDriver<unknown, DataRow>
type RegisteredResource = ResourceConfig<unknown, DataRow>
type RegisteredRuntime = ResourceRuntime<DataRow, unknown>

function storeDriver<TSource, Row extends DataRow>(
  driver: DataSourceDriver<TSource, Row>
) {
  return driver as unknown as RegisteredDriver
}

function storeResource<TSource, Row extends DataRow>(
  resource: ResourceConfig<TSource, Row>
) {
  return resource as unknown as RegisteredResource
}

function storeRuntime<TSource, Row extends DataRow>(
  runtime: ResourceRuntime<Row, TSource>
) {
  return runtime as unknown as RegisteredRuntime
}

export function defineResource<TSource, Row extends DataRow = DataRow>(
  resource: ResourceConfig<TSource, Row>
) {
  return resource
}

export function defineResourceRuntime<Row extends DataRow = DataRow>(
  runtime: ResourceRuntime<Row>
) {
  return runtime
}

export class DataSourceRegistry {
  private drivers = new Map<string, RegisteredDriver>()
  private resources = new Map<string, RegisteredResource>()
  private runtimes = new Map<string, RegisteredRuntime>()

  registerDriver<TSource = unknown, Row extends DataRow = DataRow>(
    id: string,
    driver: DataSourceDriver<TSource, Row>
  ) {
    const registeredDriver = storeDriver(driver)
    const existing = this.drivers.get(id)

    if (existing) {
      if (existing !== registeredDriver) {
        warnOnce(
          `[fable-ui] Driver "${id}" is already registered. Keeping the latest registration.`
        )
      }
    }

    this.drivers.set(id, registeredDriver)
    return this
  }

  registerResource<TSource, Row extends DataRow = DataRow>(
    resource: ResourceConfig<TSource, Row>
  ) {
    const registeredResource = storeResource(resource)
    const existing = this.resources.get(resource.id)

    if (existing) {
      if (JSON.stringify(existing) !== JSON.stringify(registeredResource)) {
        warnOnce(
          `[fable-ui] Resource "${resource.id}" is already registered. Keeping the latest registration.`
        )
      }
    }

    this.resources.set(resource.id, registeredResource)
    return this
  }

  registerResourceRuntime<TSource = unknown, Row extends DataRow = DataRow>(
    resourceId: string,
    runtime: ResourceRuntime<Row, TSource>
  ) {
    const registeredRuntime = storeRuntime(runtime)
    const existing = this.runtimes.get(resourceId)

    if (existing && existing !== registeredRuntime) {
      warnOnce(
        `[fable-ui] Runtime for resource "${resourceId}" is already registered. Keeping the latest registration.`
      )
    }

    this.runtimes.set(resourceId, registeredRuntime)
    return this
  }

  getResource<TSource = unknown, Row extends DataRow = DataRow>(
    resourceId: string
  ) {
    return this.resources.get(resourceId) as
      ResourceConfig<TSource, Row> | undefined
  }

  listResources() {
    return Array.from(this.resources.values())
  }

  resolve<TSource = unknown, Row extends DataRow = DataRow>(
    resourceId: string
  ) {
    const resource = this.resources.get(resourceId)

    if (!resource) {
      throw new Error(`Fable resource "${resourceId}" is not registered.`)
    }

    const driver = this.drivers.get(resource.driver)

    if (!driver) {
      throw new Error(
        `Fable driver "${resource.driver}" for resource "${resourceId}" is not registered.`
      )
    }

    return {
      resource: resource as unknown as ResourceConfig<TSource, Row>,
      driver: driver as unknown as DataSourceDriver<TSource, Row>,
      runtime: this.runtimes.get(resourceId) as
        ResourceRuntime<Row, TSource> | undefined,
    }
  }

  async list<Row extends DataRow = DataRow>(
    resourceId: string,
    query: DataQuery = {},
    ctx: DataSourceContext = {}
  ): Promise<DataQueryResult<Row>> {
    const { resource, driver, runtime } = this.resolve<unknown, Row>(resourceId)
    const result = runtime?.list
      ? await runtime.list(resource, query, ctx)
      : await driver.list(resource, query, ctx, runtime)

    return {
      ...result,
      rows: resource.transformRows
        ? resource.transformRows(result.rows)
        : result.rows,
    }
  }

  async get<Row extends DataRow = DataRow>(
    resourceId: string,
    rowId: string,
    ctx: DataSourceContext = {}
  ): Promise<Row | null> {
    const { resource, driver, runtime } = this.resolve<unknown, Row>(resourceId)

    if (runtime?.get) {
      return runtime.get(resource, rowId, ctx) as
        Promise<Row | null> | Row | null
    }

    return driver.get ? driver.get(resource, rowId, ctx, runtime) : null
  }

  async executeAction(
    input: DataActionInput,
    ctx: DataSourceContext = {}
  ): Promise<DataActionResult> {
    const { resource, driver, runtime } = this.resolve(input.resourceId)

    if (runtime?.executeAction) {
      return runtime.executeAction(input, resource, ctx)
    }

    if (!driver.executeAction) {
      throw new Error(
        `Fable resource "${input.resourceId}" does not support actions.`
      )
    }

    return driver.executeAction(input, resource, ctx, runtime)
  }

  getAgentResourceManifest(): AgentResourceManifest {
    return {
      resources: this.listResources().map((resource) => ({
        id: resource.id,
        label: resource.label,
        entityLabel: resource.entityLabel,
        description: resource.agent?.description,
        aliases: resource.agent?.aliases,
        useWhen: resource.agent?.useWhen,
        avoidWhen: resource.agent?.avoidWhen,
        columns: resource.columns.map(({ key, label, type, description }) => ({
          key,
          label,
          type,
          description,
        })),
        filters: resource.filters?.map(({ key, label, type, options }) => ({
          key,
          label,
          type,
          options,
        })),
        sort: resource.sort,
        actions: resource.actions?.map(
          ({
            id,
            label,
            description,
            variant,
            requiresConfirmation,
            fields,
          }) => ({
            id,
            label,
            description,
            variant,
            requiresConfirmation,
            fields,
          })
        ),
      })),
    }
  }
}

export const fableRegistry = new DataSourceRegistry()

"use client"

import * as React from "react"

import { fableRegistry, type DataSourceRegistry } from "./registry"
import { getDataValue } from "./format"
import type {
  DataActionInput,
  DataCell,
  DataColumn,
  DataQuery,
  DataQueryResult,
  DataRow,
  DataSourceContext,
  RenderedDataQuery,
  RenderedDataResult,
  RenderedDataSnapshot,
  RenderedDataValue,
} from "./types"

const EMPTY_CONTEXT: DataSourceContext = {}
const MAX_CACHE_ENTRIES = 50
const MAX_SNAPSHOT_ROWS = 100
const MAX_SNAPSHOT_COLUMNS = 12
const MAX_SNAPSHOT_BYTES = 64 * 1024

type CachedQuery = {
  resourceId: string
  promise: Promise<DataQueryResult<DataRow>>
}

type PublishRenderedDataInput<Row extends DataRow = DataRow> = {
  token: string
  resourceId: string
  title: string
  entityLabel: string
  query: DataQuery
  columns: DataColumn[]
  filterKeys: string[]
  sortKeys: string[]
  result: DataQueryResult<Row>
}

function serializeQueryValue(
  value: unknown,
  seen = new WeakSet<object>()
): string {
  if (value === undefined) return "undefined"
  if (value === null) return "null"
  if (typeof value === "string") return `string:${JSON.stringify(value)}`
  if (typeof value === "boolean") return `boolean:${value}`
  if (typeof value === "number") {
    return Number.isFinite(value)
      ? `number:${value}`
      : `number:${String(value)}`
  }
  if (typeof value === "bigint") return `bigint:${value}`
  if (value instanceof Date) return `date:${value.toISOString()}`

  if (typeof value !== "object") {
    throw new Error("Fable data query filters must be serializable values.")
  }

  if (seen.has(value)) {
    throw new Error("Fable data query filters cannot contain circular values.")
  }

  seen.add(value)
  let serialized: string

  if (Array.isArray(value)) {
    serialized = `array:[${value
      .map((item) => serializeQueryValue(item, seen))
      .join(",")}]`
  } else {
    const prototype = Object.getPrototypeOf(value)

    if (prototype !== Object.prototype && prototype !== null) {
      seen.delete(value)
      throw new Error("Fable data query filters contain an unsupported value.")
    }

    serialized = `object:{${Object.entries(value)
      .sort(([left], [right]) => left.localeCompare(right))
      .map(
        ([key, item]) =>
          `${JSON.stringify(key)}:${serializeQueryValue(item, seen)}`
      )
      .join(",")}}`
  }
  seen.delete(value)
  return serialized
}

function createDataQueryCacheKey(resourceId: string, query: DataQuery) {
  return [
    serializeQueryValue(resourceId),
    serializeQueryValue(query.search),
    serializeQueryValue(query.filters),
    serializeQueryValue(query.sort),
    serializeQueryValue(query.cursor),
    serializeQueryValue(query.page),
    serializeQueryValue(query.pageSize),
  ].join("|")
}

function toRenderedDataValue(
  value: unknown,
  seen = new WeakSet<object>()
): RenderedDataValue {
  if (
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean"
  ) {
    return value
  }

  if (value === undefined) {
    return null
  }

  if (typeof value === "number") {
    return Number.isFinite(value) ? value : String(value)
  }

  if (typeof value === "bigint") {
    return value.toString()
  }

  if (value instanceof Date) {
    return value.toISOString()
  }

  if (Array.isArray(value)) {
    if (seen.has(value)) {
      throw new Error("Rendered data contains a circular value.")
    }

    seen.add(value)
    const result = value.map((item) => toRenderedDataValue(item, seen))
    seen.delete(value)
    return result
  }

  if (typeof value === "object") {
    if (seen.has(value)) {
      throw new Error("Rendered data contains a circular value.")
    }

    const prototype = Object.getPrototypeOf(value)

    if (prototype !== Object.prototype && prototype !== null) {
      throw new Error("Rendered data contains an unsupported value.")
    }

    seen.add(value)
    const result = Object.fromEntries(
      Object.entries(value).map(([key, item]) => [
        key,
        toRenderedDataValue(item, seen),
      ])
    )
    seen.delete(value)
    return result
  }

  return String(value)
}

function toRenderedCellValue(value: unknown): DataCell {
  if (value === null || value === undefined) return null
  if (typeof value === "string" || typeof value === "boolean") return value
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : String(value)
  }
  if (typeof value === "bigint") return value.toString()
  if (value instanceof Date) return value.toISOString()
  return String(value)
}

function createRenderedDataSnapshot<Row extends DataRow>({
  resourceId,
  title,
  entityLabel,
  query,
  columns,
  filterKeys,
  sortKeys,
  result,
}: Omit<PublishRenderedDataInput<Row>, "token">): RenderedDataResult {
  const visibleColumns = columns.filter((column) => !column.hidden)

  if (
    result.rows.length > MAX_SNAPSHOT_ROWS ||
    visibleColumns.length > MAX_SNAPSHOT_COLUMNS
  ) {
    return { status: "unavailable", resourceId, reason: "too-large" }
  }

  try {
    const allowedFilterKeys = new Set(filterKeys)
    const allowedSortKeys = new Set(sortKeys)
    const sanitizedQuery: RenderedDataQuery = {
      search: query.search,
      filters: query.filters
        ? Object.fromEntries(
            Object.entries(query.filters)
              .filter(([key]) => allowedFilterKeys.has(key))
              .sort(([left], [right]) => left.localeCompare(right))
              .map(([key, value]) => [key, toRenderedDataValue(value)])
          )
        : undefined,
      sort:
        query.sort && allowedSortKeys.has(query.sort.key)
          ? query.sort
          : undefined,
      page: result.page ?? query.page ?? 1,
      pageSize: result.pageSize ?? query.pageSize ?? result.rows.length,
    }
    const snapshot: RenderedDataSnapshot = {
      resourceId,
      title,
      entityLabel,
      scope: "current-view",
      capturedAt: new Date().toISOString(),
      query: sanitizedQuery,
      columns: visibleColumns.map(
        ({ key, label, description, type, align }) => ({
          key,
          label,
          description,
          type,
          align,
        })
      ),
      rows: result.rows.map((row) =>
        Object.fromEntries(
          visibleColumns.map((column) => [
            column.key,
            toRenderedCellValue(getDataValue(row, column.key)),
          ])
        )
      ),
      totalRows: result.totalRows ?? result.rows.length,
      page: result.page ?? query.page ?? 1,
      pageSize: result.pageSize ?? query.pageSize ?? result.rows.length,
    }

    if (
      new TextEncoder().encode(JSON.stringify(snapshot)).byteLength >
      MAX_SNAPSHOT_BYTES
    ) {
      return { status: "unavailable", resourceId, reason: "too-large" }
    }

    return { status: "available", data: snapshot }
  } catch {
    return { status: "unavailable", resourceId, reason: "too-large" }
  }
}

function createProviderStore(
  registry: DataSourceRegistry,
  context: DataSourceContext
) {
  const queries = new Map<string, CachedQuery>()
  const resolvedKeys: string[] = []
  const renderedDataByToken = new Map<string, RenderedDataResult>()
  const activeSnapshotTokens = new Map<string, string[]>()
  let tokenCounter = 0

  function removeResolvedKey(key: string) {
    const index = resolvedKeys.indexOf(key)

    if (index >= 0) {
      resolvedKeys.splice(index, 1)
    }
  }

  function rememberResolvedKey(key: string) {
    removeResolvedKey(key)
    resolvedKeys.push(key)

    while (resolvedKeys.length > MAX_CACHE_ENTRIES) {
      const oldest = resolvedKeys.shift()

      if (oldest) {
        queries.delete(oldest)
      }
    }
  }

  function listResource<Row extends DataRow = DataRow>(
    resourceId: string,
    query: DataQuery = {},
    options: { force?: boolean } = {}
  ): Promise<DataQueryResult<Row>> {
    let key: string

    try {
      key = createDataQueryCacheKey(resourceId, query)
    } catch (error) {
      return Promise.reject(error)
    }

    const existing = queries.get(key)

    if (existing && !options.force) {
      return existing.promise as Promise<DataQueryResult<Row>>
    }

    if (existing) {
      queries.delete(key)
      removeResolvedKey(key)
    }

    const promise = Promise.resolve(
      registry.list<Row>(resourceId, query, context)
    )
    const entry: CachedQuery = {
      resourceId,
      promise: promise as Promise<DataQueryResult<DataRow>>,
    }
    queries.set(key, entry)

    promise.then(
      () => {
        if (queries.get(key) === entry) {
          rememberResolvedKey(key)
        }
      },
      () => {
        if (queries.get(key) === entry) {
          queries.delete(key)
          removeResolvedKey(key)
        }
      }
    )

    return promise
  }

  function beginRenderedData(resourceId: string) {
    const token = `${resourceId}:${++tokenCounter}`
    const tokens = activeSnapshotTokens.get(resourceId) ?? []
    activeSnapshotTokens.set(resourceId, [...tokens, token])
    return token
  }

  function endRenderedData(resourceId: string, token: string) {
    const tokens = activeSnapshotTokens.get(resourceId)

    if (!tokens?.includes(token)) {
      return
    }

    const remainingTokens = tokens.filter(
      (currentToken) => currentToken !== token
    )
    renderedDataByToken.delete(token)

    if (remainingTokens.length > 0) {
      activeSnapshotTokens.set(resourceId, remainingTokens)
    } else {
      activeSnapshotTokens.delete(resourceId)
    }
  }

  function invalidateResource(resourceId: string) {
    for (const [key, entry] of queries) {
      if (entry.resourceId === resourceId) {
        queries.delete(key)
        removeResolvedKey(key)
      }
    }

    for (const token of activeSnapshotTokens.get(resourceId) ?? []) {
      renderedDataByToken.delete(token)
    }
    activeSnapshotTokens.delete(resourceId)
  }

  function publishRenderedData<Row extends DataRow>(
    input: PublishRenderedDataInput<Row>
  ) {
    if (!activeSnapshotTokens.get(input.resourceId)?.includes(input.token)) {
      return
    }

    renderedDataByToken.set(input.token, createRenderedDataSnapshot(input))
  }

  function getRenderedData(resourceId: string): RenderedDataResult {
    const tokens = activeSnapshotTokens.get(resourceId) ?? []

    for (let index = tokens.length - 1; index >= 0; index -= 1) {
      const snapshot = renderedDataByToken.get(tokens[index])

      if (snapshot) {
        return snapshot
      }
    }

    return {
      status: "unavailable",
      resourceId,
      reason: "not-rendered",
    }
  }

  return {
    listResource,
    invalidateResource,
    beginRenderedData,
    endRenderedData,
    publishRenderedData,
    getRenderedData,
  }
}

type FableDataContextValue = {
  registry: DataSourceRegistry
  context: DataSourceContext
  listResource: ReturnType<typeof createProviderStore>["listResource"]
  invalidateResource: ReturnType<
    typeof createProviderStore
  >["invalidateResource"]
  beginRenderedData: ReturnType<typeof createProviderStore>["beginRenderedData"]
  endRenderedData: ReturnType<typeof createProviderStore>["endRenderedData"]
  publishRenderedData: ReturnType<
    typeof createProviderStore
  >["publishRenderedData"]
  getRenderedData: ReturnType<typeof createProviderStore>["getRenderedData"]
}

const FableDataContext = React.createContext<FableDataContextValue | null>(null)

export function FableDataProvider({
  registry = fableRegistry,
  context = EMPTY_CONTEXT,
  children,
}: {
  registry?: DataSourceRegistry
  context?: DataSourceContext
  children: React.ReactNode
}) {
  const store = React.useMemo(
    () => createProviderStore(registry, context),
    [context, registry]
  )
  const value = React.useMemo(
    () => ({ registry, context, ...store }),
    [context, registry, store]
  )

  return (
    <FableDataContext.Provider value={value}>
      {children}
    </FableDataContext.Provider>
  )
}

export function useFableDataContext() {
  const value = React.useContext(FableDataContext)

  if (!value) {
    throw new Error(
      "useFableDataContext must be used within FableDataProvider."
    )
  }

  return value
}

export function useOptionalFableDataContext() {
  return React.useContext(FableDataContext)
}

export function useFableResource(resourceId: string) {
  const { registry, context, invalidateResource, listResource } =
    useFableDataContext()
  const resource = registry.getResource(resourceId)

  const list = React.useCallback(
    (query: DataQuery = {}) => listResource(resourceId, query),
    [listResource, resourceId]
  )

  const runAction = React.useCallback(
    async (input: Omit<DataActionInput, "resourceId">) => {
      const result = await registry.executeAction(
        { ...input, resourceId },
        context
      )

      if (result.invalidate) {
        invalidateResource(resourceId)
      }

      return result
    },
    [context, invalidateResource, registry, resourceId]
  )

  return {
    resource,
    list,
    runAction,
  }
}
